def transform(grid):
    h = len(grid); w = len(grid[0])
    from collections import Counter
    flat = Counter(c for row in grid for c in row)
    bg = flat.most_common(1)[0][0]
    # find line: full row or column not bg
    line_col = None; line_row = None; line_color = None
    for j in range(w):
        col = [grid[i][j] for i in range(h)]
        if len(set(col)) == 1 and col[0] != bg:
            line_col = j; line_color = col[0]
    if line_col is None:
        for i in range(h):
            row = grid[i]
            if len(set(row)) == 1 and row[0] != bg:
                line_row = i; line_color = row[0]
    cells = [(i, j, grid[i][j]) for i in range(h) for j in range(w)
             if grid[i][j] not in (bg, line_color)]
    out = [[bg] * w for _ in range(h)]
    if line_col is not None:
        for i in range(h):
            out[i][line_col] = line_color
        minc = min(j for _, j, _ in cells); maxc = max(j for _, j, _ in cells)
        if maxc < line_col:  # shape left of line
            shift = (line_col - 1) - maxc
            eight = minc + shift - 1
        else:
            shift = (line_col + 1) - minc
            eight = maxc + shift + 1
        for i, j, v in cells:
            out[i][j + shift] = v
        if 0 <= eight < w:
            for i in range(h):
                out[i][eight] = 8
    else:
        for j in range(w):
            out[line_row][j] = line_color
        minr = min(i for i, _, _ in cells); maxr = max(i for i, _, _ in cells)
        if maxr < line_row:  # shape above line
            shift = (line_row - 1) - maxr
            eight = minr + shift - 1
        else:
            shift = (line_row + 1) - minr
            eight = maxr + shift + 1
        for i, j, v in cells:
            out[i + shift][j] = v
        if 0 <= eight < h:
            for j in range(w):
                out[eight][j] = 8
    return out
